"use client";

/**
 * Ctrl+K overlay shell; the domain layer supplies the groups.
 *
 * Owner A — design system. Knows nothing about commands: it filters the groups
 * it is handed, keeps a single flat active index across group boundaries (so
 * ArrowDown walks from the last item of one group into the first of the next),
 * and reports the chosen id. Registering shortcuts is `useCommandPalette`'s job.
 */
import { useMemo, useState } from "react";
import type { KeyboardEvent, ReactElement } from "react";
import { cn } from "@/lib/cn";
import { isNavKey, matchesQuery, moveActiveIndex } from "./_lib/list-navigation";
import { CONTROL_BORDER, OVERLAY, SURFACE } from "./_lib/tokens";
import { useDismissableLayer, useScrollLock } from "./_lib/use-dismissable-layer";

export type CommandGroup = { heading: string; items: readonly CommandItemSpec[] };

export type CommandItemSpec = { id: string; label: string; hint?: string; shortcut?: string };

export type CommandPaletteProps = { open: boolean; groups: readonly CommandGroup[]; placeholder?: string; onClose: () => void; onSelect: (id: string) => void };

type FlatRow = { item: CommandItemSpec; heading: string; index: number };

/**
 * Filter the groups and number the surviving items in render order. The flat
 * index is what makes arrow navigation continuous across headings.
 */
export function flattenGroups(
  groups: readonly CommandGroup[],
  query: string,
): { rows: FlatRow[]; sections: { heading: string; rows: FlatRow[] }[] } {
  const rows: FlatRow[] = [];
  const sections: { heading: string; rows: FlatRow[] }[] = [];

  for (const group of groups) {
    const kept: FlatRow[] = [];
    for (const item of group.items) {
      const haystack = `${item.label} ${item.hint ?? ""} ${group.heading}`;
      if (!matchesQuery(haystack, query)) continue;
      const row = { item, heading: group.heading, index: rows.length };
      rows.push(row);
      kept.push(row);
    }
    if (kept.length > 0) sections.push({ heading: group.heading, rows: kept });
  }

  return { rows, sections };
}

export function CommandPalette(props: CommandPaletteProps): ReactElement | null {
  const { open, groups, placeholder = "Search commands…", onClose, onSelect } = props;

  const [query, setQuery] = useState("");
  const [activeIndex, setActiveIndex] = useState(0);

  const panelRef = useDismissableLayer<HTMLDivElement>({ open, onDismiss: onClose });
  useScrollLock(open);

  const { rows, sections } = useMemo(
    () => flattenGroups(groups, query),
    [groups, query],
  );

  // A fresh open starts from a clean query. Adjusting state during render on an
  // open/closed transition is the documented alternative to an effect here: the
  // reset lands in the same commit as the open, with no extra paint.
  const [wasOpen, setWasOpen] = useState(open);
  if (open !== wasOpen) {
    setWasOpen(open);
    if (open) {
      setQuery("");
      setActiveIndex(0);
    }
  }

  const choose = (id: string) => {
    onSelect(id);
    onClose();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const key = event.key;
    if (isNavKey(key)) {
      event.preventDefault();
      setActiveIndex((index) => moveActiveIndex(index, key, rows.length));
      return;
    }
    if (key === "Enter") {
      event.preventDefault();
      const row = rows[activeIndex];
      if (row) choose(row.item.id);
    }
  };

  if (!open) return null;

  return (
    <div className={cn(OVERLAY, "flex items-start justify-center p-4 pt-24")}>
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-label="Command palette"
        onKeyDown={handleKeyDown}
        className={cn(SURFACE, "w-full max-w-xl overflow-hidden rounded-lg shadow-2xl")}
      >
        <input
          autoFocus
          type="text"
          role="combobox"
          aria-expanded
          aria-controls="command-palette-list"
          aria-autocomplete="list"
          value={query}
          placeholder={placeholder}
          onChange={(event) => {
            setQuery(event.target.value);
            setActiveIndex(0);
          }}
          className={cn(
            "w-full border-b bg-transparent px-4 py-3 text-sm outline-none placeholder:text-black/40",
            CONTROL_BORDER,
          )}
        />

        <div id="command-palette-list" role="listbox" className="max-h-80 overflow-y-auto py-1">
          {rows.length === 0 ? (
            <p className="px-4 py-6 text-center text-xs text-black/45">
              No commands match “{query}”
            </p>
          ) : null}

          {sections.map((section) => (
            <div key={section.heading} className="py-1">
              <p className="px-4 pb-1 text-[10px] font-semibold uppercase tracking-wide text-black/40">
                {section.heading}
              </p>
              {section.rows.map((row) => (
                <button
                  key={row.item.id}
                  type="button"
                  role="option"
                  aria-selected={row.index === activeIndex}
                  tabIndex={-1}
                  onMouseEnter={() => setActiveIndex(row.index)}
                  onClick={() => choose(row.item.id)}
                  className={cn(
                    "flex w-full items-center gap-3 px-4 py-2 text-left text-sm",
                    row.index === activeIndex && "bg-surface-muted",
                  )}
                >
                  <span className="flex-1 truncate text-black/85 dark:text-white/85">
                    {row.item.label}
                  </span>
                  {row.item.hint !== undefined ? (
                    <span className="truncate text-[11px] text-black/45">
                      {row.item.hint}
                    </span>
                  ) : null}
                  {row.item.shortcut !== undefined ? (
                    <kbd className="rounded border border-black/15 px-1 text-[10px] text-black/55">
                      {row.item.shortcut}
                    </kbd>
                  ) : null}
                </button>
              ))}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
"use client";

/**
 * Builds the Ctrl+K command groups from the actor's permissions and flags.
 *
 * Must call (do not reimplement): can, isEnabled
 */
import { useCallback, useMemo, useState } from "react";
import { isEnabled } from "@/lib/feature-flags";
import type { CommandGroup } from "@/components/ui/command-palette";
import { buildCommandGroups } from "./command-groups";
import { orgFlagContext } from "./flag-context";
import { useKeyboardShortcut } from "./use-keyboard-shortcut";
import { useOrg } from "./use-org";

export const COMMAND_PALETTE_SHORTCUT: readonly string[] = ["mod", "k"];

export function useCommandPalette(): {
  open: boolean;
  setOpen: (open: boolean) => void;
  groups: readonly CommandGroup[];
} {
  const { org, actor, flags } = useOrg();
  const [open, setOpen] = useState(false);

  // The palette itself is a flag; when it is off the shortcut must not bind.
  const paletteEnabled =
    flags.command_palette === true ||
    isEnabled("command_palette", orgFlagContext(org, actor));

  const toggle = useCallback(() => setOpen((current) => !current), []);
  useKeyboardShortcut(COMMAND_PALETTE_SHORTCUT, toggle, paletteEnabled);

  const groups = useMemo(
    () => (paletteEnabled ? buildCommandGroups(org, actor, flags) : []),
    [paletteEnabled, org, actor, flags],
  );

  return { open: open && paletteEnabled, setOpen, groups };
}
/**
 * Builds the Ctrl+K command list for one actor.
 *
 * Every entry names the permission and/or flag that gates it and is then
 * filtered through `can()` and `isEnabled()` — the palette must never offer a
 * command the actor would be refused, and it must never invent its own idea of
 * who may do what. Kept pure so the filtering can be tested directly.
 */
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import {
  activityResource,
  billingResource,
  organizationResource,
} from "@/components/domain/permission/resources";
import type {
  CommandGroup,
  CommandItemSpec,
} from "@/components/ui/command-palette";
import type { FeatureFlagKey, FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { PermissionAction, PermissionResource } from "@/types/permission";
import { orgFlagContext } from "./flag-context";

/** A palette entry plus the gates it depends on. */
export interface CommandSpec extends CommandItemSpec {
  readonly heading: string;
  readonly action?: PermissionAction;
  readonly flag?: FeatureFlagKey;
  /** Which resource the permission is asked about; defaults to the org. */
  readonly scope?: "organization" | "billing" | "activity";
}

export const COMMAND_SPECS: readonly CommandSpec[] = [
  { heading: "Create", id: "create:issue", label: "New issue", shortcut: "c", action: "issue:create" },
  { heading: "Create", id: "create:project", label: "New project", action: "project:create" },
  { heading: "Create", id: "create:invite", label: "Invite teammate", action: "member:invite" },
  { heading: "Go to", id: "nav:issues", label: "Issues", shortcut: "g i", action: "issue:read" },
  { heading: "Go to", id: "nav:projects", label: "Projects", shortcut: "g p", action: "project:read" },
  { heading: "Go to", id: "nav:board", label: "Board", shortcut: "g b", action: "issue:read", flag: "kanban_board" },
  { heading: "Go to", id: "nav:members", label: "Members", action: "member:read" },
  {
    heading: "Go to",
    id: "nav:activity",
    label: "Activity",
    action: "activity:read",
    flag: "activity_feed",
    scope: "activity",
  },
  {
    heading: "Go to",
    id: "nav:billing",
    label: "Billing",
    action: "org:manage_billing",
    scope: "billing",
  },
  {
    heading: "Export",
    id: "export:issues",
    label: "Export issues as CSV",
    hint: "Downloads the current filter",
    action: "issue:read",
    flag: "csv_export",
  },
  {
    heading: "Export",
    id: "export:activity",
    label: "Export audit log as CSV",
    action: "activity:export",
    flag: "csv_export",
    scope: "activity",
  },
];

function resourceFor(spec: CommandSpec, actor: Actor): PermissionResource {
  switch (spec.scope) {
    case "billing":
      return billingResource(actor.orgId);
    case "activity":
      return activityResource(actor.orgId);
    default:
      // Creation and navigation are not scoped to an existing row, so the
      // organization is the resource the role matrix is asked about.
      return organizationResource(actor.orgId);
  }
}

export function buildCommandGroups(
  org: Organization,
  actor: Actor,
  flags: FeatureFlagSnapshot,
): readonly CommandGroup[] {
  const context = orgFlagContext(org, actor);
  // The snapshot was evaluated when the layout rendered; a flag flipped since
  // then is still honoured by re-evaluating against the live context.
  const flagOn = (flag: FeatureFlagKey): boolean =>
    flags[flag] === true || isEnabled(flag, context);

  const groups = new Map<string, CommandItemSpec[]>();

  for (const spec of COMMAND_SPECS) {
    if (spec.flag !== undefined && !flagOn(spec.flag)) continue;
    if (
      spec.action !== undefined &&
      !can(actor, spec.action, resourceFor(spec, actor))
    ) {
      continue;
    }
    const items = groups.get(spec.heading) ?? [];
    items.push({
      id: spec.id,
      label: spec.label,
      ...(spec.hint !== undefined ? { hint: spec.hint } : {}),
      ...(spec.shortcut !== undefined ? { shortcut: spec.shortcut } : {}),
    });
    groups.set(spec.heading, items);
  }

  return [...groups.entries()].map(([heading, items]) => ({ heading, items }));
}
