    <div className={cn(OVERLAY, "flex items-start justify-center p-4 pt-24")}>
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-label="Command palette"
        onKeyDown={handleKeyDown}
        className={cn(SURFACE, "w-full max-w-xl overflow-hidden rounded-lg shadow-2xl")}
