        <input
          autoFocus
          type="text"
          role="combobox"
          aria-expanded
          aria-controls="command-palette-list"
          aria-autocomplete="list"
          value={query}
          placeholder={placeholder}
          onChange={(event) => {
            setQuery(event.target.value);
            setActiveIndex(0);
          }}
          className={cn(
            "w-full border-b bg-transparent px-4 py-3 text-sm outline-none placeholder:text-black/40",
            CONTROL_BORDER,
          )}
